def transformCheckStatus(data):
	removeKeys = {'itemId', 'stepSortOrder', 'sortOrder', 'parentStepId', 'itemDescription'}
	renameKeys = {
		'parentStepName': 'Step',
		'itemType': 'Type',
		'itemName': 'Name',
		'checkResult': 'Result',
		'value': 'Value',
		'status': 'Status',
		'required': 'Required'
	}

	result = []
	for row in data:
		newRow = {}
		for key, value in row.items():
			if key in removeKeys: continue
			newKey = renameKeys.get(key, key)
			newRow[newKey] = value

		if not newRow.get('Step'):
			newRow['Step'] = newRow.get('Name')
			newRow['Name'] = None

		result.append(newRow)

	return result

system.perspective.openPopup('Check Status', 'kanoa/core/templates/displays/tablePopup', {'value': {'data': transformCheckStatus(self.view.custom.workOrderEventCheckStatus)}}, title='Check Status', draggable=True, resizable=True, showCloseIcon=True)

return

transforms.code:

ci = system.util.jsonDecode(value['conditionInfo'])
if value['conditionName'] == 'counter':
	counterName = system.kanoa.utilities.getFieldValue('counterName', system.kanoa.asset.getCounter({'counterId': ci['counterId']}))
	lastGeneratedDate = system.date.format(value['lastGeneratedDate'], 'YYMMdd') if value['lastGeneratedDate'] else ''
	return "%s counter every %s counts. Last work order generated on %s at %s counts"%(counterName.title(), ci['valueThreshold'], value['lastGeneratedDate'], value['lastGeneratedValue'] or '')
elif value['conditionName'] == 'runHour':
	lastGeneratedDate = system.date.format(value['lastGeneratedDate'], 'YYMMdd') if value['lastGeneratedDate'] else value['createdDate']

	runDict = system.kanoa.utilities.convertDatasetToDict(system.kanoa.event.getAssetStateEventsSummary({'assetId': value['assetId'], 'startDate': lastGeneratedDate, 'endDate': system.date.now(), 'durationSecs': 0, 'showChanged': None, 'showDowntimeOnly': False}), 'stateName', 'durationSecs')
	runHours = (runDict['Running'] or 0.0) / 3600.0
	return "Triggered every %s run hours. Last work order generated on %s at %s hours"%(ci['valueThreshold'], lastGeneratedDate, round(runHours,1))

return value['conditionName']

instances = []
for row in value:
	metaDataValue = system.util.jsonDecode(row['metaDataValue'])
	instances.append({
						'comment': metaDataValue.get('comment'), 
						'pinned': metaDataValue.get('pinned', False), 
						'tStamp': row['createdDate'], 
						'userId': row['createdBy'],
						'metaData': system.util.jsonEncode({'workOrderEventMetaDataId': row['workOrderEventMetaDataId']})
					})

return {'data': instances}

def buildOption(text, value, bgColor):
	return {
			"text": text,
			"value": value,
			"unselectedStyle": {"classes": ""},
			"selectedStyle": {"classes": "", "backgroundColor": bgColor, 'color': system.kanoa.utilities.getContrastingColor(bgColor)}
		}

options = []
for k,v in value.items():
	options.append(buildOption(v['workOrderEventStatusName'], v['workOrderEventStatusId'], v['workOrderEventStatusColor']))

return options

customMethods.script:
info = dict(self.view.custom.workOrderEventInfo)
keysToKeep = {"workOrderEventId", "workOrderId", "assetId", "workOrderEventName", "workOrderEventStatusId", "workOrderPriorityId", "maintenanceSubTypeId", "requestedBy", "requestedDate", "assignedTo", "dueDate"}
workOrderEventInfo = {k: info[k] for k in keysToKeep if k in info}

if info['workOrderEventStatusName'] == 'Open' and info['assignedTo'] is not None:
	workOrderEventInfo['workOrderEventStatusId'] = next((v['workOrderEventStatusId'] for v in self.view.custom.workOrderEventStatus.values() if v.get('workOrderEventStatusName') == 'Assigned'), None)

retVal, msg = system.kanoa.cmms.updateWorkOrderEvent(workOrderEventInfo, self.view.custom.security.userId)
if msg: system.perspective.sendMessage('showWarningToast', {'message': "Couldn't update work order. %s"%msg})
else: 
	try:
		workOrderEventStatusName = self.view.custom.workOrderEventStatus[str(workOrderEventInfo['workOrderEventStatusId'])]['workOrderEventStatusName']
		system.perspective.sendMessage('showSuccessfulToast', {'message': 'Work order has been updated'})
		self.view.refreshBinding("custom.workOrderEventInfo")
		self.view.refreshBinding("custom.workOrderEventStatusChange")		

		system.perspective.sendMessage('refreshWorkOrders', {'workOrderEventStatusName': workOrderEventStatusName})	
	except:
		pass

return
